// @generated by project-forge — visual-geometry-check.mjs (pure-Node deterministic SVG geometry verifier, zero Chrome dependency)

export const GEOMETRY_VIOLATION_CODES = Object.freeze({
  NODE_OVERLAP: 'NODE_OVERLAP',
  OUT_OF_BOUNDS: 'OUT_OF_BOUNDS',
  EDGE_CROSSES_BOX: 'EDGE_CROSSES_BOX',
  EMPTY_ACTIVE_DIAGRAM: 'EMPTY_ACTIVE_DIAGRAM',
})

const CMD_RE = /([MLHVQCSZ])([^MLHVQCSZ]*)/gi
const NUM_RE = /-?\d+(?:\.\d+)?/g

export function parseOrthogonalPathPoints(pathD) {
  const d = String(pathD || '').trim()
  if (!d) return []
  const pts = []
  let cx = 0
  let cy = 0
  for (const m of d.matchAll(CMD_RE)) {
    const cmd = m[1].toUpperCase()
    const nums = (m[2].match(NUM_RE) || []).map(Number).filter(Number.isFinite)
    if (cmd === 'M' || cmd === 'L') {
      for (let i = 0; i + 1 < nums.length; i += 2) {
        cx = nums[i]
        cy = nums[i + 1]
        pts.push({ x: cx, y: cy })
      }
    } else if (cmd === 'H') {
      for (const x of nums) { cx = x; pts.push({ x: cx, y: cy }) }
    } else if (cmd === 'V') {
      for (const y of nums) { cy = y; pts.push({ x: cx, y: cy }) }
    } else if (cmd === 'Q') {
      for (let i = 0; i + 3 < nums.length; i += 4) {
        const qx = nums[i]
        const qy = nums[i + 1]
        cx = nums[i + 2]
        cy = nums[i + 3]
        pts.push({ x: qx, y: qy }, { x: cx, y: cy })
      }
    } else if (cmd === 'C') {
      for (let i = 0; i + 5 < nums.length; i += 6) {
        const x1 = nums[i]
        const y1 = nums[i + 1]
        const x2 = nums[i + 2]
        const y2 = nums[i + 3]
        cx = nums[i + 4]
        cy = nums[i + 5]
        pts.push({ x: (x1 + x2) / 2, y: (y1 + y2) / 2 }, { x: cx, y: cy })
      }
    }
  }
  return pts
}

function segmentIntersectsRectInterior(p1, p2, rect, eps = 0.5) {
  const rx1 = rect.x + eps
  const rx2 = rect.x + rect.w - eps
  const ry1 = rect.y + eps
  const ry2 = rect.y + rect.h - eps
  if (rx2 <= rx1 || ry2 <= ry1) return false

  const dx = p2.x - p1.x
  const dy = p2.y - p1.y
  let t0 = 0
  let t1 = 1

  const clip = (p, q) => {
    if (Math.abs(p) < 1e-9) return q >= 0
    const r = q / p
    if (p < 0) {
      if (r > t1) return false
      if (r > t0) t0 = r
    } else {
      if (r < t0) return false
      if (r < t1) t1 = r
    }
    return true
  }

  if (!clip(-dx, p1.x - rx1)) return false
  if (!clip(dx, rx2 - p1.x)) return false
  if (!clip(-dy, p1.y - ry1)) return false
  if (!clip(dy, ry2 - p1.y)) return false
  return t1 - t0 > 1e-4
}

function isBoxValid(b) {
  return b && Number.isFinite(b.x) && Number.isFinite(b.y) && Number.isFinite(b.w) && Number.isFinite(b.h)
}

function computeOverlapArea(a, b, eps = 0.5) {
  const ox = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x)
  const oy = Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y)
  if (ox > eps && oy > eps) return Math.round(ox * oy * 10) / 10
  return 0
}

export function verifyDiagramGeometry(diagramLayout, {
  allowContainerOverlap = true,
  active = true,
  epsilon = 0.5,
} = {}) {
  const diagramId = String(diagramLayout?.id || diagramLayout?.kind || 'diagram')
  const width = Number(diagramLayout?.width)
  const height = Number(diagramLayout?.height)
  const rawNodes = Array.isArray(diagramLayout?.nodes) ? diagramLayout.nodes : []
  const rawEdges = Array.isArray(diagramLayout?.edges) ? diagramLayout.edges : []
  const violations = []
  let overlaps = 0
  let crossings = 0
  let outOfBounds = 0

  if (active && rawNodes.length === 0) {
    violations.push({
      code: GEOMETRY_VIOLATION_CODES.EMPTY_ACTIVE_DIAGRAM,
      diagramId,
      message: `Active diagram "${diagramId}" has 0 nodes`,
    })
  }

  const checkNodes = allowContainerOverlap
    ? rawNodes.filter((n) => n && !n.isContainer && n.kind !== 'container')
    : rawNodes.filter(Boolean)

  for (const n of rawNodes) {
    if (!isBoxValid(n) || !Number.isFinite(width) || !Number.isFinite(height)) {
      outOfBounds += 1
      violations.push({
        code: GEOMETRY_VIOLATION_CODES.OUT_OF_BOUNDS,
        diagramId,
        targetId: String(n?.id || 'unknown'),
        message: 'Node or canvas has non-finite geometry coordinates',
      })
      continue
    }
    if (n.x < -epsilon || n.y < -epsilon || n.x + n.w > width + epsilon || n.y + n.h > height + epsilon) {
      outOfBounds += 1
      violations.push({
        code: GEOMETRY_VIOLATION_CODES.OUT_OF_BOUNDS,
        diagramId,
        targetId: String(n.id || 'unknown'),
        message: `Node "${n.id}" (${n.x},${n.y},${n.w}x${n.h}) exceeds canvas ${width}x${height}`,
      })
    }
  }

  // 按 X 轴排序构建扫描线与前缀最大右边界索引（O((N + E) log N + K)）
  const sortedNodes = []
  for (let i = 0; i < checkNodes.length; i += 1) {
    const b = checkNodes[i]
    if (!isBoxValid(b)) continue
    sortedNodes.push({
      box: b,
      id: String(b.id || i),
      x1: b.x,
      x2: b.x + b.w,
      y1: b.y,
      y2: b.y + b.h,
      origIdx: i,
    })
  }
  sortedNodes.sort((a, b) => (a.x1 - b.x1) || (a.y1 - b.y1) || (a.origIdx - b.origIdx))

  const prefixMaxX2 = new Array(sortedNodes.length)
  let runningMaxX2 = -Infinity
  for (let i = 0; i < sortedNodes.length; i += 1) {
    if (sortedNodes[i].x2 > runningMaxX2) runningMaxX2 = sortedNodes[i].x2
    prefixMaxX2[i] = runningMaxX2
  }

  // X 轴排序扫描线检测节点重叠：一旦右侧节点 x1 >= a.x2 - epsilon 即可提前中止内层循环
  for (let i = 0; i < sortedNodes.length; i += 1) {
    const a = sortedNodes[i]
    const xLimit = a.x2 - epsilon
    for (let j = i + 1; j < sortedNodes.length; j += 1) {
      const b = sortedNodes[j]
      if (b.x1 >= xLimit) break
      if (b.y2 <= a.y1 + epsilon || b.y1 >= a.y2 - epsilon) continue
      const area = computeOverlapArea(a.box, b.box, epsilon)
      if (area > 0) {
        overlaps += 1
        violations.push({
          code: GEOMETRY_VIOLATION_CODES.NODE_OVERLAP,
          diagramId,
          aId: a.id,
          bId: b.id,
          area,
          message: `Nodes "${a.box.id}" and "${b.box.id}" overlap (area=${area})`,
        })
      }
    }
  }

  const lowerBoundPrefixMaxX2 = (threshold) => {
    let lo = 0
    let hi = sortedNodes.length
    while (lo < hi) {
      const mid = (lo + hi) >>> 1
      if (prefixMaxX2[mid] <= threshold) lo = mid + 1
      else hi = mid
    }
    return lo
  }
  const upperBoundX1 = (limit) => {
    let lo = 0
    let hi = sortedNodes.length
    while (lo < hi) {
      const mid = (lo + hi) >>> 1
      if (sortedNodes[mid].x1 < limit) lo = mid + 1
      else hi = mid
    }
    return lo
  }

  for (const edge of rawEdges) {
    if (!edge) continue
    const pts = Array.isArray(edge.points) && edge.points.length >= 2
      ? edge.points
      : parseOrthogonalPathPoints(edge.pathD)
    if (pts.length < 2) continue

    for (const p of pts) {
      if (!Number.isFinite(p?.x) || !Number.isFinite(p?.y)
        || p.x < -epsilon || p.y < -epsilon || p.x > width + epsilon || p.y > height + epsilon) {
        outOfBounds += 1
        violations.push({
          code: GEOMETRY_VIOLATION_CODES.OUT_OF_BOUNDS,
          diagramId,
          targetId: String(edge.id || `${edge.fromId}->${edge.toId}`),
          message: `Edge point (${p?.x},${p?.y}) exceeds canvas ${width}x${height}`,
        })
        break
      }
    }

    const fromId = String(edge.fromId || edge.from || '')
    const toId = String(edge.toId || edge.to || '')
    let edgeCrossed = false
    for (let k = 0; k < pts.length - 1 && !edgeCrossed; k += 1) {
      const p1 = pts[k]
      const p2 = pts[k + 1]
      if (!Number.isFinite(p1?.x) || !Number.isFinite(p1?.y) || !Number.isFinite(p2?.x) || !Number.isFinite(p2?.y)) continue
      const segMinX = Math.min(p1.x, p2.x)
      const segMaxX = Math.max(p1.x, p2.x)
      const segMinY = Math.min(p1.y, p2.y)
      const segMaxY = Math.max(p1.y, p2.y)
      const lo = lowerBoundPrefixMaxX2(segMinX + epsilon)
      const hi = upperBoundX1(segMaxX - epsilon)
      for (let idx = lo; idx < hi; idx += 1) {
        const cand = sortedNodes[idx]
        if (cand.x2 <= segMinX + epsilon || cand.y2 <= segMinY + epsilon || cand.y1 >= segMaxY - epsilon) continue
        const bid = String(cand.box.id || '')
        if (bid && (bid === fromId || bid === toId)) continue
        if (segmentIntersectsRectInterior(p1, p2, cand.box, epsilon)) {
          crossings += 1
          edgeCrossed = true
          violations.push({
            code: GEOMETRY_VIOLATION_CODES.EDGE_CROSSES_BOX,
            diagramId,
            edgeId: String(edge.id || `${fromId}->${toId}`),
            boxId: bid,
            message: `Edge "${edge.id || `${fromId}->${toId}`}" crosses node "${bid}"`,
          })
          break
        }
      }
    }
  }

  return {
    ok: violations.length === 0,
    diagramId,
    stats: {
      nodeCount: rawNodes.length,
      edgeCount: rawEdges.length,
      overlaps,
      crossings,
      outOfBounds,
    },
    violations,
  }
}

export function verifyMultiDiagramGeometry(diagrams, opts = {}) {
  const perDiagram = {}
  let totalViolations = 0
  const entries = diagrams && typeof diagrams === 'object' ? Object.entries(diagrams) : []
  for (const [id, layout] of entries) {
    if (!layout || typeof layout !== 'object') continue
    const res = verifyDiagramGeometry({ ...layout, id: layout.id || id }, opts)
    perDiagram[id] = res
    totalViolations += res.violations.length
  }
  return {
    ok: totalViolations === 0,
    diagramCount: Object.keys(perDiagram).length,
    totalViolations,
    perDiagram,
  }
}
